def risk_and_response(m,base):
 phase,owner,trigger,method,verify,fail,gate,metric,risk=base
 if m['force']=='SHOULD' or m['force']=='MAY':
  risk='MEDIUM' if risk != 'CRITICAL' else 'HIGH'
  fail='FLAG_FOR_REVIEW' if m['force']=='SHOULD' else 'LOG_ONLY'
 if m['force']=='MUST_NOT' and owner in ('CORPUS_SERVICE','POLICY_GATEWAY'):
  fail='DENY_PROTECTED_ACTION'
 return phase,owner,trigger,method,verify,fail,gate,metric,risk

profiles=[]
for m in master:
 nr=next((v for v in RULES if v['id']==m['id']),None)
 phase,owner,trigger,method,verify,fail,gate,metric,risk=risk_and_response(m,category_map[m['category']])
 if nr:
  phase=nr['phase'];owner=nr['actor'];trigger=nr['trigger_event'];method=nr['enforcement_method'];fail=nr['failure_action'];metric=nr['impact_metric_id'];risk=nr['risk_tier'];verify=('DETERMINISTIC' if method in ('SERVER_POLICY','SCHEMA_VALIDATOR','CORPUS_SERVICE') else 'HYBRID' if method in ('EVIDENCE_VALIDATOR','HOST_CONTEXT','OUTPUT_GUARD','SERVER_AND_REVIEW') else 'HUMAN_REVIEW')
 applicable = 'Apply only if event, phase, actor authorization and scoped rule predicate all match; require policy admission.'
 if m['force']=='MAY':
  expectation='This rule permits the option when authorized; it is not a required action: '+m['text_en']
 elif m['force']=='SHOULD':
  expectation='Recommended, unless a documented and authorized reason warrants deviation: '+m['text_en']
 else: expectation=m['text_en']
 # Use real expected behavior, but don't conflate target enforcement with implementation status.
 proof={'DETERMINISTIC':'Host-issued decision and deterministic positive/negative tests with exact rule revision',
        'HYBRID':'Structured tool trace plus independent review of scope and evidence links',
        'HUMAN_REVIEW':'Source citation and independently recorded expert review with positive/negative examples',
        'HUMAN_SEMANTIC_REVIEW':'Verified corpus excerpts, explicit warrant, competing cases and reviewer decision'}[verify]
 test='Positive: compliant operation is permitted; negative: violating attempt is blocked, downgraded, or flagged according to the declared failure action; require independently assessed trace.'
 profiles.append(dict(id=m['id'],rule_text_en=m['text_en'],rule_kind=m['kind'],force=m['force'],category=m['category'],phase=phase,applies_to=owner,trigger_event=trigger,trigger_predicate=applicable,expected_behavior=expectation,enforcement_target=method,verification_mode=verify,failure_action=fail,gate_reference=gate,required_evidence=proof,proposed_test=test,impact_metric_id=metric,risk_tier=risk,applicability_status='UNVERIFIED_REQUIRES_RULE_SPECIFIC_REVIEW',enforcement_status='NOT_VERIFIED',profile_origin='EXPLICIT_NEW_RULE_PROPOSAL' if nr else 'CATEGORY_BASED_INFERENCE',review_status='PENDING_INDEPENDENT_REVIEW'))
profile_keys=list(profiles[0].keys())
dump_csv(BASE/'LISAN_RULE_EXECUTION_PROFILES_230.csv',profiles,profile_keys)

